// Package argparse is a minimal command-line argument parser.
package argparse

import (
	"errors"
	"fmt"
	"io"
	"strconv"
	"strings"
	"text/tabwriter"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flag struct {
	name, short, usage, def string
	boolVal                 *bool
	strVal                  *string
}

type positional struct {
	name, usage string
	val         *string
}

// Parser holds flag and positional definitions and the parsed results.
type Parser struct {
	name, desc  string
	flags       []*flag
	positionals []*positional
	rest        []string
}

// New returns a parser for the named program.
func New(name, desc string) *Parser {
	return &Parser{name: name, desc: desc}
}

// Bool defines a boolean flag. short may be empty.
func (p *Parser) Bool(name, short, usage string) *bool {
	v := new(bool)
	p.flags = append(p.flags, &flag{name: name, short: short, usage: usage, boolVal: v})
	return v
}

// String defines a flag that takes a value. short may be empty.
func (p *Parser) String(name, short, def, usage string) *string {
	v := new(string)
	*v = def
	p.flags = append(p.flags, &flag{name: name, short: short, usage: usage, def: def, strVal: v})
	return v
}

// Positional defines a required positional argument. Order of calls is order on the command line.
func (p *Parser) Positional(name, usage string) *string {
	v := new(string)
	p.positionals = append(p.positionals, &positional{name: name, usage: usage, val: v})
	return v
}

// Args returns positional arguments left over after the defined ones.
func (p *Parser) Args() []string {
	return p.rest
}

// Parse parses args, which should not include the program name.
func (p *Parser) Parse(args []string) error {
	var pos []string
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			pos = append(pos, args[i+1:]...)
			break
		}
		if arg == "-" || !strings.HasPrefix(arg, "-") {
			pos = append(pos, arg)
			continue
		}
		if arg == "-h" || arg == "--help" {
			return ErrHelp
		}

		long := strings.HasPrefix(arg, "--")
		body := strings.TrimPrefix(strings.TrimPrefix(arg, "-"), "-")
		name, value, hasValue := strings.Cut(body, "=")
		display := arg[:len(arg)-len(body)] + name

		f := p.lookup(name, long)
		if f == nil {
			return fmt.Errorf("unknown flag: %s", display)
		}

		if f.boolVal != nil {
			*f.boolVal = true
			if hasValue {
				b, err := strconv.ParseBool(value)
				if err != nil {
					return fmt.Errorf("invalid boolean %q for %s", value, display)
				}
				*f.boolVal = b
			}
			continue
		}

		if !hasValue {
			if i+1 >= len(args) {
				return fmt.Errorf("flag %s needs a value", display)
			}
			i++
			value = args[i]
		}
		*f.strVal = value
	}

	if len(pos) < len(p.positionals) {
		return fmt.Errorf("missing argument: %s", p.positionals[len(pos)].name)
	}
	for i, d := range p.positionals {
		*d.val = pos[i]
	}
	p.rest = pos[len(p.positionals):]
	return nil
}

func (p *Parser) lookup(name string, long bool) *flag {
	if name == "" {
		return nil
	}
	for _, f := range p.flags {
		if (long && f.name == name) || (!long && f.short == name) {
			return f
		}
	}
	return nil
}

// WriteHelp writes a help message generated from the definitions.
func (p *Parser) WriteHelp(w io.Writer) {
	fmt.Fprintf(w, "Usage: %s [flags]", p.name)
	for _, d := range p.positionals {
		fmt.Fprintf(w, " <%s>", d.name)
	}
	fmt.Fprintln(w)
	if p.desc != "" {
		fmt.Fprintf(w, "\n%s\n", p.desc)
	}

	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	if len(p.positionals) > 0 {
		fmt.Fprintln(tw, "\nArguments:")
		for _, d := range p.positionals {
			fmt.Fprintf(tw, "  %s\t%s\n", d.name, d.usage)
		}
	}
	fmt.Fprintln(tw, "\nFlags:")
	for _, f := range p.flags {
		fmt.Fprintf(tw, "  %s\t%s\n", f.label(), f.help())
	}
	fmt.Fprintln(tw, "  -h, --help\tshow this help")
	tw.Flush()
}

func (f *flag) label() string {
	s := "    --" + f.name
	if f.short != "" {
		s = "-" + f.short + ", --" + f.name
	}
	if f.strVal != nil {
		s += " <value>"
	}
	return s
}

func (f *flag) help() string {
	if f.def != "" {
		return fmt.Sprintf("%s (default %q)", f.usage, f.def)
	}
	return f.usage
}
