package main

import (
	"errors"
	"fmt"
	"os"

	"example.com/greet/argparse"
)

func main() {
	p := argparse.New("greet", "Print a greeting.")
	verbose := p.Bool("verbose", "v", "print extra detail")
	output := p.String("output", "o", "out.txt", "file to write to")
	name := p.Positional("name", "who to greet")

	if err := p.Parse(os.Args[1:]); err != nil {
		if errors.Is(err, argparse.ErrHelp) {
			p.WriteHelp(os.Stdout)
			return
		}
		fmt.Fprintln(os.Stderr, "error:", err)
		p.WriteHelp(os.Stderr)
		os.Exit(2)
	}

	fmt.Println(*verbose, *output, *name, p.Args())
}
```

Behaviour:

- Accepted forms are `--name`, `--name=value`, `--name value`, `-n`, `-n value`, and `-n=value`.
- `--` ends flag parsing; everything after it is positional.
- Flags and positionals can be mixed in any order.
- Defined positionals are required. Extras are in `Args()`.
- Combined short flags (`-abc`) are not supported.
- A positional starting with `-`, such as `-5`, needs `--` before it.
- Values are strings; the caller converts numbers.
- Duplicate flag names are not checked; the first definition wins.

