import express from "express";
import pg from "pg";

const pool = new pg.Pool(); // reads PG* environment variables
const router = express.Router();

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

function encodeCursor(row) {
  return Buffer.from(JSON.stringify([row.cursor_ts, String(row.id)])).toString("base64url");
}

function decodeCursor(cursor) {
  try {
    const [ts, id] = JSON.parse(Buffer.from(cursor, "base64url").toString("utf8"));
    if (typeof ts === "string" && typeof id === "string" && /^\d+$/.test(id)) {
      return { ts, id };
    }
  } catch {
    // fall through
  }
  return null;
}

router.get("/orders", async (req, res, next) => {
  const limit = req.query.limit === undefined ? DEFAULT_LIMIT : Number(req.query.limit);
  if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) {
    return res.status(400).json({ error: `limit must be an integer from 1 to ${MAX_LIMIT}` });
  }

  let after = null;
  if (req.query.cursor !== undefined) {
    after = typeof req.query.cursor === "string" ? decodeCursor(req.query.cursor) : null;
    if (!after) {
      return res.status(400).json({ error: "invalid cursor" });
    }
  }

  // Fetch one extra row to learn whether another page exists.
  const where = after ? "WHERE (created_at, id) < ($2::timestamptz, $3::bigint)" : "";
  const params = after ? [limit + 1, after.ts, after.id] : [limit + 1];

  try {
    const { rows } = await pool.query(
      `SELECT id, customer_id, status, total, created_at,
              to_char(created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') AS cursor_ts
         FROM orders
         ${where}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      params,
    );

    const page = rows.slice(0, limit);
    const hasMore = rows.length > limit;

    res.json({
      data: page.map(({ cursor_ts, ...order }) => order),
      next_cursor: hasMore ? encodeCursor(page[page.length - 1]) : null,
    });
  } catch (err) {
    // Class 22 = data exception, e.g. a cursor timestamp PostgreSQL cannot parse.
    if (after && typeof err.code === "string" && err.code.startsWith("22")) {
      return res.status(400).json({ error: "invalid cursor" });
    }
    next(err);
  }
});

export default router;
