On timeout, `fetch` rejects with a `DOMException` named `"TimeoutError"`:

```js
try {
  const response = await fetch(url, { signal: AbortSignal.timeout(5000) });
} catch (err) {
  if (err.name === "TimeoutError") {
    // timed out
  } else {
    throw err;
  }
}
```

The timeout also covers reading the body (`response.json()`, `response.text()`), not only the headers.

`AbortSignal.timeout` needs Node 17.3+ or a browser from 2022 or later. For older runtimes:

```js
const controller = new AbortController();
const timer = setTimeout(() => controller.abort(), 5000);
try {
  const response = await fetch(url, { signal: controller.signal });
} finally {
  clearTimeout(timer);
}
```

Here the error name is `"AbortError"`, and the timer stops once headers arrive.

```js
function throttle(fn, wait) {
  let lastRun = 0;
  let timer = null;
  let lastArgs;
  let lastThis;

  const run = () => {
    lastRun = Date.now();
    timer = null;
    fn.apply(lastThis, lastArgs);
  };

  return function (...args) {
    lastArgs = args;
    lastThis = this;
    const remaining = wait - (Date.now() - lastRun);
    if (remaining <= 0) {
      clearTimeout(timer);
      run();
    } else if (timer === null) {
      timer = setTimeout(run, remaining);
    }
  };
}

function onScroll() {
  console.log(window.scrollY);
}

window.addEventListener("scroll", throttle(onScroll, 200), { passive: true });
```

The first event runs at once. Later events within 200 ms collapse into one trailing call, so the handler always sees the final scroll position.
